bool IsChinese()
{
    // "auto" | "en" | "zh"
    const auto lang = Config::Instance()->MenuLanguage.value_or_default();
    if (lang == "en")
        return false;
    if (lang == "zh")
        return true;
    // auto: primary language id 0x04 is Chinese
    return (GetUserDefaultUILanguage() & 0xFF) == 0x04;
}

